import{profileData}from"../../profile-data.js";export const TERMINAL_CONFIG={VERSION:`${(new Date).getFullYear()}.0.1`,WELCOME_MESSAGE:"Welcome to my 127.0.0.1",INITIAL_COMMAND:"$ code session --agent=viewer --profile=andrei",HELP_HEADER:`Andrei-Alexandru Paciurca | Terminal Resume CLI v${(new Date).getFullYear()}.0.1`};export const COMMANDS={RESUME:"resume",HELP:"help",CLEAR:"clear",LS:"ls",CAT:"cat"};export const RESUME_FLAGS=[{long:"--about",short:"-a",description:"Show a summary of who I am",action:()=>profileData.summary},{long:"--experience",short:"-e",description:"List professional experience",action:()=>formatExperiences()},{long:"--skills",short:"-s",description:"Show technical skill groups",action:()=>formatSkills()},{long:"--education",short:"-edu",description:"Show educational background",action:()=>formatEducation()},{long:"--contact",short:"-c",description:"Get contact information",action:()=>formatContact()},{long:"--linkedin",short:"-l",description:"Open LinkedIn profile",action:()=>(window.open(profileData.contact.linkedinUrl,"_blank"),`Opening LinkedIn: ${profileData.contact.linkedinUrl}`)},{long:"--github",short:"-g",description:"Open GitHub profile",action:()=>(window.open(profileData.contact.githubUrl,"_blank"),`Opening GitHub: ${profileData.contact.githubUrl}`)},{long:"--email",short:"-m",description:"Send an email",action:()=>(window.location.href=`mailto:${profileData.contact.email}`,`Opening mail client for: ${profileData.contact.email}`)},{long:"--photo",short:"-p",description:"Show profile photo",action:()=>`       .---.\n      /     \\\n      | () () |\n       \\  ^  /\n        |||||\n        |||||\n\nOriginal photo present at: ${window.location.origin}/${profileData.profilePictureUrl}`},{long:"--help",short:"-h",description:"Show this help message"},{long:"--right",short:"-r",description:"Toggle right-click protection",hidden:!0}];export const VIRTUAL_FILES=["experience.md","skills.md","education.md","contact.txt","about_me.txt","photo.jpg"];function formatExperiences(){return profileData.experiences.map(n=>`${n.company} | ${n.title}\n${n.period}\n${n.location}\n\n${n.bullets.map(n=>`• ${n}`).join("\n")}`).join("\n\n"+"-".repeat(40)+"\n\n")}function formatSkills(){return profileData.skillGroups.map(n=>`[ ${n.label} ]\n${n.items.map(n=>n.label).join(", ")}`).join("\n\n")}function formatEducation(){return profileData.education.map(n=>`${n.title}\n${n.details}\n${n.extra||""}`).join("\n\n")}function formatContact(){return`Email: ${profileData.contact.email}\nPhone: ${profileData.contact.phone}\nLinkedIn: ${profileData.contact.linkedinUrl}\nGitHub: ${profileData.contact.githubUrl}`}